def is_nested(string):
    count = 0
    has_nested = False
    for ch in string:
        if ch == '[':
            count += 1
        else:  # ch == ']'
            if count > 0:
                count -= 1
                if count > 0:
                    has_nested = True
            else:
                count = 0
    return has_nested
